package com.imageproc.pipeline

import scala.concurrent.{Future, ExecutionContext}
import scala.concurrent.ExecutionContext.Implicits.global
import java.nio.file.{Files, Path, Paths}
import java.security.MessageDigest
import javax.imageio.ImageIO
import java.awt.image.BufferedImage

object ImageConfig {
  val baseUploadDir: Path = Paths.get("/var/app/uploads")
  val baseThumbnailDir: Path = Paths.get("/var/app/thumbnails")
  val allowedExtensions: Set[String] = Set("png", "jpg", "jpeg", "gif", "webp")
  val maxFilenameLength: Int = 255
}

class PathNormalizer {
  // Normalize path segments by resolving encoded characters
  def decodeSegment(segment: String): String = {
    segment
      .replace("%2F", "/")
      .replace("%2f", "/")
      .replace("%5C", "\\")
      .replace("%5c", "\\")
  }

  // Validate individual path component
  def isValidComponent(component: String): Boolean = {
    !component.contains("..") && 
    !component.contains("~") &&
    !component.startsWith("/") &&
    !component.startsWith("\\")
  }

  // Build safe relative path from user-provided segments
  def buildRelativePath(segments: Seq[String]): Option[String] = {
    val decoded = segments.map(decodeSegment)
    if (decoded.forall(isValidComponent)) {
      Some(decoded.mkString("/"))
    } else {
      None
    }
  }
}

class ImageValidator {
  def validateExtension(filename: String): Boolean = {
    val ext = filename.lastIndexOf('.') match {
      case -1 => ""
      case i => filename.substring(i + 1).toLowerCase
    }
    ImageConfig.allowedExtensions.contains(ext)
  }

  def validateDimensions(img: BufferedImage): Boolean = {
    img.getWidth <= 4096 && img.getHeight <= 4096
  }
}

class ThumbnailGenerator {
  def generateThumbnail(source: BufferedImage, maxDim: Int): BufferedImage = {
    val ratio = Math.min(maxDim.toDouble / source.getWidth, maxDim.toDouble / source.getHeight)
    val newWidth = (source.getWidth * ratio).toInt
    val newHeight = (source.getHeight * ratio).toInt
    val thumbnail = new BufferedImage(newWidth, newHeight, BufferedImage.TYPE_INT_ARGB)
    val g = thumbnail.createGraphics()
    g.drawImage(source, 0, 0, newWidth, newHeight, null)
    g.dispose()
    thumbnail
  }
}

class SecurityAuditor {
  private def computeHash(path: String): String = {
    val md = MessageDigest.getInstance("SHA-256")
    md.update(path.getBytes("UTF-8"))
    md.digest().map("%02x".format(_)).mkString
  }

  // Verify the resolved path is within the allowed base directory
  def verifyContainment(resolvedPath: Path, baseDir: Path): Boolean = {
    val normalizedResolved = resolvedPath.normalize()
    val normalizedBase = baseDir.normalize()
    normalizedResolved.startsWith(normalizedBase)
  }

  def auditAccess(userPath: String, baseDir: Path): Option[Path] = {
    val candidate = baseDir.resolve(userPath)
    if (verifyContainment(candidate, baseDir)) {
      Some(candidate.normalize())
    } else {
      None
    }
  }
}

class ImageProcessingPipeline {
  private val normalizer = new PathNormalizer()
  private val validator = new ImageValidator()
  private val thumbnailGen = new ThumbnailGenerator()
  private val auditor = new SecurityAuditor()

  // Process user request to generate thumbnail
  def processRequest(userSegments: Seq[String], outputName: String): Future[Either[String, Path]] = {
    Future {
      // Step 1: Build relative path from user segments
      val relativePath = normalizer.buildRelativePath(userSegments)
      relativePath match {
        case None => Left("Invalid path segments")
        case Some(relPath) => Right(relPath)
      }
    }.flatMap {
      case Left(err) => Future.successful(Left(err))
      case Right(relPath) => resolveAndProcess(relPath, outputName)
    }
  }

  private def resolveAndProcess(relPath: String, outputName: String): Future[Either[String, Path]] = {
    Future {
      // Step 2: Validate filename extension
      if (!validator.validateExtension(relPath)) {
        return Future.successful(Left("Invalid file extension"))
      }

      // Step 3: Security audit on the source path
      val sourcePath = auditor.auditAccess(relPath, ImageConfig.baseUploadDir)
      sourcePath match {
        case None => Left("Access denied: path traversal detected")
        case Some(safePath) => Right(safePath)
      }
    }.flatMap {
      case Left(err) => Future.successful(Left(err))
      case Right(safePath) => generateOutput(safePath, outputName)
    }
  }

  private def generateOutput(sourcePath: Path, outputName: String): Future[Either[String, Path]] = {
    Future {
      // Step 4: Read and validate image
      if (!Files.exists(sourcePath)) {
        return Future.successful(Left("Source file not found"))
      }

      val sourceImage = ImageIO.read(sourcePath.toFile)
      if (sourceImage == null || !validator.validateDimensions(sourceImage)) {
        return Future.successful(Left("Invalid image"))
      }

      // Step 5: Generate thumbnail
      val thumbnail = thumbnailGen.generateThumbnail(sourceImage, 256)

      // Step 6: Resolve output path - uses the raw outputName for the thumbnail
      // The output undergoes its own containment check
      val sanitizedOutput = outputName.replaceAll("[^a-zA-Z0-9._-]", "")
      val outputPath = ImageConfig.baseThumbnailDir.resolve(sanitizedOutput)

      // Write thumbnail
      Files.createDirectories(outputPath.getParent)
      ImageIO.write(thumbnail, "png", outputPath.toFile)
      Right(outputPath)
    }
  }
}

// HTTP handler simulation
object ImageHandler {
  private val pipeline = new ImageProcessingPipeline()

  def handleThumbnailRequest(pathParam: String, outputParam: String): Future[Either[String, Path]] = {
    // Split path parameter on forward slash to get segments
    val segments = pathParam.split("/").toSeq.filter(_.nonEmpty)

    if (segments.isEmpty || outputParam.isEmpty) {
      Future.successful(Left("Missing parameters"))
    } else {
      pipeline.processRequest(segments, outputParam)
    }
  }
}
